import {
  azimuthFromDegrees,
  isOnTerrain,
  normalizeAzimuth,
  type Azimuth,
  type SoldierId,
  type TerrainDataset,
  type Vec2,
} from '#sim';

// The trainee's deployment intent (docs/adr/0012): for each soldier, at most
// one destination and one facing. This is all the trainee decides. The path to
// the destination is generated by the simulation's navigation and is never part
// of the plan; neither are the low-level orders that carry the plan out.

/** A map point in metres east and north of the terrain origin. */
export interface MapPoint {
  readonly east: number;
  readonly north: number;
}

export interface SoldierDeploymentPlan {
  readonly soldierId: SoldierId;
  /** Where the soldier is to go, or `null` to stay where it is. */
  readonly destination: MapPoint | null;
  /**
   * Facing chosen by the trainee, degrees clockwise from grid north in [0, 360),
   * or `null` when the trainee has not set one and the default applies (see
   * `defaultFacing`).
   */
  readonly facingDegrees: number | null;
}

/** A plan with no destination and no facing: the soldier stays as it is. */
export function emptyPlan(soldierId: SoldierId): SoldierDeploymentPlan {
  return { soldierId, destination: null, facingDegrees: null };
}

export function samePlan(a: SoldierDeploymentPlan, b: SoldierDeploymentPlan): boolean {
  return (
    a.soldierId === b.soldierId &&
    a.facingDegrees === b.facingDegrees &&
    (a.destination === null
      ? b.destination === null
      : b.destination !== null &&
        a.destination.east === b.destination.east &&
        a.destination.north === b.destination.north)
  );
}

export const toVec2 = (p: MapPoint): Vec2 => ({ x: p.east, y: p.north });
export const toMapPoint = (p: Vec2): MapPoint => ({ east: p.x, north: p.y });

/** Degrees in [0, 360) for an azimuth, the form plans store. */
export function facingDegreesOf(azimuth: Azimuth): number {
  const degrees = (normalizeAzimuth(azimuth) * 180) / Math.PI;
  return degrees >= 360 ? 0 : degrees;
}

/**
 * The facing the soldier will take on arrival when the trainee has set none:
 * the direction of the last piece of its path (it keeps facing the way it
 * walked), or, without a destination or with nowhere to walk, its current
 * facing. This is a placeholder, not a tactical recommendation.
 */
export function defaultFacing(path: readonly Vec2[], currentFacing: Azimuth): Azimuth {
  for (let k = path.length - 1; k > 0; k -= 1) {
    const to = path[k];
    const from = path[k - 1];
    if (!to || !from) continue;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    if (Math.hypot(dx, dy) > 1e-9) return normalizeAzimuth(Math.atan2(dx, dy));
  }
  return currentFacing;
}

/** The facing a plan resolves to, and whether the trainee chose it. */
export function resolvedFacing(
  plan: SoldierDeploymentPlan,
  path: readonly Vec2[],
  currentFacing: Azimuth,
): { readonly azimuth: Azimuth; readonly explicit: boolean } {
  return plan.facingDegrees === null
    ? { azimuth: defaultFacing(path, currentFacing), explicit: false }
    : { azimuth: azimuthFromDegrees(plan.facingDegrees), explicit: true };
}

/** Problems with the plan's own values (not reachability); empty when valid. */
export function validateDeploymentPlan(
  plan: SoldierDeploymentPlan,
  terrain: TerrainDataset,
): string[] {
  const problems: string[] = [];
  const f = plan.facingDegrees;
  if (f !== null && !(Number.isFinite(f) && f >= 0 && f < 360)) {
    problems.push(`facing ${String(f)} is not a bearing in [0, 360) degrees`);
  }
  const d = plan.destination;
  if (d !== null) {
    if (!Number.isFinite(d.east) || !Number.isFinite(d.north)) {
      problems.push('destination is not a finite map point');
    } else if (!isOnTerrain(terrain, d.east, d.north)) {
      problems.push('destination is off the map');
    }
  }
  return problems;
}

// ---------------------------------------------------------------------------
// Serialized form. Nothing is persisted by the application yet; this is the
// one supported exchange format for deployment plans, and it is versioned so
// that older data is refused rather than misread.

export const DEPLOYMENT_PLAN_SCHEMA = 'ambush.deployment-plans';
export const DEPLOYMENT_PLAN_SCHEMA_VERSION = 1;

export interface DeploymentPlanSet {
  /** Fingerprint of the exercise scenario the plans were made for (`Exercise.scenarioFingerprint`). */
  readonly scenarioFingerprint: string;
  readonly plans: readonly SoldierDeploymentPlan[];
}

export class DeploymentPlanError extends Error {
  override name = 'DeploymentPlanError';
}

/**
 * Deterministic JSON for a plan set: fixed key order, plans in the order
 * given (the exercise uses roster order), numbers in JavaScript's shortest
 * round-trip form.
 */
export function serializeDeploymentPlans(set: DeploymentPlanSet): string {
  return JSON.stringify({
    schema: DEPLOYMENT_PLAN_SCHEMA,
    schemaVersion: DEPLOYMENT_PLAN_SCHEMA_VERSION,
    scenarioFingerprint: set.scenarioFingerprint,
    plans: set.plans.map((p) => ({
      soldierId: p.soldierId,
      destination: p.destination && { east: p.destination.east, north: p.destination.north },
      facingDegrees: p.facingDegrees,
    })),
  });
}

/**
 * Reads serialized plans for a scenario. Refuses, with a `DeploymentPlanError`
 * that says why: other schemas and versions, plans made for a different
 * scenario (or a different organization template or version, which change the
 * fingerprint), unknown or repeated soldiers, malformed values, and waypoint
 * chains from before Phase 3.7. There is deliberately no migration rule from a
 * waypoint chain to a single destination: choosing which waypoint was "meant"
 * would be guessing the trainee's intent.
 */
export function parseDeploymentPlans(
  text: string,
  expected: { readonly scenarioFingerprint: string; readonly soldierIds: readonly SoldierId[] },
): DeploymentPlanSet {
  const fail = (message: string): never => {
    throw new DeploymentPlanError(`Deployment plans not loaded: ${message}.`);
  };
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    return fail('the text is not JSON');
  }
  const record = (value: unknown, what: string): Record<string, unknown> =>
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : fail(`${what} must be an object`);
  const root = record(data, 'the data');
  const plansValue = root['plans'];
  const looksLikeWaypoints = (p: unknown) =>
    typeof p === 'object' && p !== null && ('waypoints' in p || 'finalFacing' in p);
  if (Array.isArray(plansValue) && plansValue.some(looksLikeWaypoints)) {
    fail(
      'they are waypoint-chain plans from before Phase 3.7; single-destination plans cannot be derived from them, so plan each soldier again',
    );
  }
  if (root['schema'] !== DEPLOYMENT_PLAN_SCHEMA)
    fail(`the schema is not "${DEPLOYMENT_PLAN_SCHEMA}"`);
  if (root['schemaVersion'] !== DEPLOYMENT_PLAN_SCHEMA_VERSION) {
    fail(
      `schema version ${JSON.stringify(root['schemaVersion'])} is not supported (this version reads ${String(DEPLOYMENT_PLAN_SCHEMA_VERSION)})`,
    );
  }
  if (root['scenarioFingerprint'] !== expected.scenarioFingerprint) {
    fail('they were made for a different scenario, organization template or template version');
  }
  if (!Array.isArray(plansValue)) return fail('"plans" must be an array');
  const known = new Set<string>(expected.soldierIds);
  const seen = new Set<string>();
  const plans = (plansValue as unknown[]).map((value, i): SoldierDeploymentPlan => {
    const what = `plan ${String(i + 1)}`;
    const plan = record(value, what);
    for (const key of Object.keys(plan)) {
      if (!['soldierId', 'destination', 'facingDegrees'].includes(key))
        fail(`${what} has unknown field "${key}"`);
    }
    const id = plan['soldierId'];
    if (typeof id !== 'string' || !known.has(id))
      fail(`${what} is for unknown soldier ${JSON.stringify(id)}`);
    if (seen.has(id as string)) fail(`soldier "${String(id)}" has two plans`);
    seen.add(id as string);
    const facing = plan['facingDegrees'];
    if (
      facing !== null &&
      !(typeof facing === 'number' && Number.isFinite(facing) && facing >= 0 && facing < 360)
    ) {
      fail(`${what} has an invalid facing`);
    }
    const dest = plan['destination'];
    let destination: MapPoint | null = null;
    if (dest !== null) {
      const d = record(dest, `${what} destination`);
      const { east, north } = d;
      if (
        typeof east !== 'number' ||
        typeof north !== 'number' ||
        !Number.isFinite(east) ||
        !Number.isFinite(north)
      ) {
        return fail(`${what} has an invalid destination`);
      }
      destination = { east, north };
    }
    return { soldierId: id as SoldierId, destination, facingDegrees: facing as number | null };
  });
  return { scenarioFingerprint: expected.scenarioFingerprint, plans };
}
